import json
from pathlib import Path
from datetime import date, timedelta

OUT = Path(__file__).parent / "data" / "synthetic" / "knowledge.jsonl"
# Each case is a curated fictional engineering situation; no external personal information.
cases=[
 dict(slug='db-index', name='Order lookup latency', component='orders database', symptom='The p95 GET /orders/{id} latency rose from 90 ms to 760 ms at peak without a matching increase in write volume.', evidence='EXPLAIN QUERY PLAN showed a full scan on orders(customer_id, created_at); a representative query returned 38,000 rows before filtering.', action='Add a composite index on (customer_id, created_at), remove the SELECT * projection, and measure the query before considering a database migration.', alternative='Migrate immediately from SQLite to PostgreSQL', downside='The index increases write cost and requires verification against realistic data skew.', measure='Compare p50/p95 latency and query plans using the same seeded workload; require p95 below 180 ms.', rollback='Drop the new index and revert the query change if write latency or query plans regress.', principle='measure_before_migrating', coaching='What does the query plan say about how many rows the database must inspect?', gotcha='The index column order must match the filter and sorting pattern.'),
 dict(slug='idempotency', name='Duplicate payments on retry', component='checkout API', symptom='Transient network failures caused clients to retry POST /payments and occasionally create two payment intents.', evidence='Request logs showed identical cart IDs posted within 200 ms, while the endpoint had no persisted idempotency key.', action='Require a client-provided idempotency key, enforce uniqueness per customer in storage, and return the original result on safe retries.', alternative='Disable client retries entirely', downside='Keys need retention and collision handling; the transactional uniqueness rule adds a database dependency.', measure='Replay concurrent duplicate requests and verify exactly one payment intent and a stable response.', rollback='Disable the new request-key enforcement behind a feature flag while retaining duplicate-payment detection.', principle='safe_retries', coaching='If the client times out after the server commits, what does it know about whether payment succeeded?', gotcha='A cache-only key is insufficient when separate workers race.'),
 dict(slug='queue', name='Email queue pressure', component='notification worker', symptom='Order-confirmation emails were delayed for 18 minutes during a marketing burst.', evidence='Queue depth climbed continuously while average worker processing stayed near 450 ms and the retry fraction grew.', action='Separate transactional messages from bulk email workloads, cap retries with exponential backoff, and add dead-letter handling.', alternative='Increase worker count indefinitely', downside='Separate queues increase operational configuration and require careful fair-share limits.', measure='Load-test 5x peak mail traffic and verify transactional queue delay stays below 60 seconds.', rollback='Route both classes through the prior shared queue if the new routing fails, with priority alerts active.', principle='protect_critical_paths', coaching='Which messages have different delivery promises, and what does queue depth tell you?', gotcha='Unlimited retries can starve fresh traffic.'),
 dict(slug='authz', name='Cross-tenant order exposure', component='order authorization', symptom='A user could fetch an order ID belonging to another tenant in a staging penetration test.', evidence='The route verified authentication but fetched records only by order_id; its query omitted tenant_id.', action='Apply tenant scoping in repository queries and add negative authorization tests at the API boundary.', alternative='Hide order IDs behind opaque identifiers', downside='Tenant scoping must be audited throughout read and export paths.', measure='Run cross-tenant request tests and verify 403/404 without information leakage on every affected endpoint.', rollback='Disable the vulnerable endpoint until authorization scope is verified; do not revert to the insecure behavior.', principle='security_first', coaching='Is a hard-to-guess ID an authorization check? What must the query enforce?', gotcha='Never treat authentication as proof of resource ownership.'),
 dict(slug='outbox', name='Lost events after transaction', component='order event publisher', symptom='A paid order sometimes had no order-created event in the analytics consumer.', evidence='A crash occurred after the database commit but before the external publish; the code treated these as one logical operation.', action='Use a transactional outbox table, publish asynchronously, and make consumers idempotent.', alternative='Publish directly before committing the order', downside='The outbox introduces cleanup, monitoring and a small delivery delay.', measure='Inject crashes between commit and publish and assert eventual at-least-once delivery without duplicate side effects.', rollback='Keep the outbox persisted and pause publishing on failure, then replay after recovery.', principle='reliable_side_effects', coaching='Can a single process atomically commit the database and send an external message?', gotcha='At-least-once delivery requires consumers to handle duplicates.'),
 dict(slug='cache', name='Stale inventory display', component='inventory cache', symptom='Customers saw in-stock labels for items that had sold out minutes earlier.', evidence='The cache TTL was 15 minutes and the inventory update route did not invalidate the relevant keys.', action='Shorten the display cache TTL, invalidate on stock updates, and recheck stock transactionally at checkout.', alternative='Trust the cache at checkout for speed', downside='More invalidations increase cache churn; rechecks add latency to checkout.', measure='Simulate stock depletion and confirm checkout never oversells, even with stale read caches.', rollback='Bypass cache reads for inventory until invalidation is proven safe.', principle='correctness_over_speed', coaching='Which parts of the product can tolerate stale data, and which must be correct immediately?', gotcha='A short TTL does not make a stale stock check safe for payment.'),
 dict(slug='migration', name='Zero-downtime schema change', component='order schema', symptom='A release adding a required delivery_region column failed for existing rows.', evidence='Migration logs showed NOT NULL applied before backfill and older worker versions still inserted rows without the new field.', action='Use expand-backfill-contract: add nullable column, deploy dual-compatible code, backfill in batches, then enforce constraint.', alternative='Apply one destructive migration during deployment', downside='The staged sequence takes additional releases and requires tracking intermediate states.', measure='Run mixed-version deployment tests and check no insert failures or lock spikes during backfill.', rollback='Roll back application behavior while keeping the backward-compatible column; never drop populated data blindly.', principle='reversible_changes', coaching='What happens when the old and new application versions run at the same time?', gotcha='Schema rollback is not always reversible once data is transformed.'),
 dict(slug='rate-limit', name='Partner traffic spikes', component='public API gateway', symptom='A partner integration saturated request workers, pushing regular customer requests into timeouts.', evidence='Request metrics showed 68% of peak traffic from one API key and retries aligned with bursts of 429 responses.', action='Apply per-client token-bucket limits, publish Retry-After semantics, and exempt health checks appropriately.', alternative='Set one global request limit for everybody', downside='Per-client limits need fair quotas and careful treatment of legitimate bursts.', measure='Load-test mixed tenants and confirm abusive clients cannot push other tenants above the agreed p95 budget.', rollback='Adjust quota configuration quickly while keeping a protective global circuit limit.', principle='fair_isolation', coaching='Would a global limit protect innocent customers from one noisy partner?', gotcha='Poorly configured retry behavior can amplify overload.'),
 dict(slug='observability', name='Unknown checkout timeouts', component='checkout tracing', symptom='Checkout requests intermittently timed out but logs did not reveal the slow dependency.', evidence='Logs lacked correlation IDs, and database and payment gateway timings were aggregated into a single request duration.', action='Propagate correlation IDs and add spans for validation, database operations and payment calls with safe redaction.', alternative='Add verbose unstructured logging everywhere', downside='Instrumentation adds overhead and demands care not to expose payment details.', measure='Reproduce timeouts and demonstrate root-cause isolation from a single trace without sensitive payloads.', rollback='Reduce tracing sampling if overhead rises, retaining essential metrics and redacted error identifiers.', principle='observability_before_guessing', coaching='Which dependency consumed the time, and can you answer without viewing customer data?', gotcha='Never put card details or tokens in trace attributes.'),
 dict(slug='bulkhead', name='Payment gateway slowdown', component='payment integration', symptom='A third-party gateway outage tied up all application workers and made unrelated order reads fail.', evidence='Connection pool metrics showed payment requests waiting 20 seconds without a timeout or concurrency cap.', action='Introduce explicit timeouts, bounded concurrency and a circuit breaker for the payment dependency.', alternative='Raise the application worker limit only', downside='Aggressive timeouts can interrupt slow but recoverable payments; thresholds need measurements.', measure='Fault-inject gateway latency and verify unrelated read endpoints stay healthy while payment calls fail predictably.', rollback='Tune breaker thresholds and disable only the breaker rule if it misfires, preserving hard timeouts.', principle='limit_blast_radius', coaching='Why should an unavailable payment provider prevent somebody from viewing an existing order?', gotcha='Do not retry non-idempotent payments blindly.'),
 dict(slug='api-version', name='Breaking API response', component='orders response contract', symptom='A mobile client crashed after an optional field was renamed in the orders response.', evidence='Contract tests covered the new client only; active old client versions still expected total_amount.', action='Restore the old field, introduce the new field additively, and define a deprecation window with consumer contract tests.', alternative='Force all clients to update immediately', downside='Supporting overlapping fields increases temporary maintenance and documentation work.', measure='Test current and previous supported client payloads and assert backward compatibility.', rollback='Reinstate the old response shape behind a versioned serializer if new clients show issues.', principle='backward_compatibility', coaching='Who consumes this API besides the service you are currently changing?', gotcha='A field rename is a breaking change even if types otherwise stay identical.'),
 dict(slug='feature-flag', name='Risky recommendation rollout', component='recommendation service', symptom='A newly launched recommendation algorithm increased checkout latency on 20% of sessions.', evidence='Canary dashboards showed higher p95 and error rate only for sessions assigned to the new feature flag.', action='Disable the canary, inspect high-latency traces, and resume gradually only with measurable guardrails.', alternative='Roll out globally and optimize afterward', downside='Feature flags create cleanup work and can complicate test matrices.', measure='Re-enable for 5% of sessions and require stable error rate and p95 for a predefined observation window.', rollback='Turn the feature flag off immediately without redeployment.', principle='controlled_rollouts', coaching='What metric tells us to stop the rollout before customers report a problem?', gotcha='Canary groups must be comparable and observability must include the flag cohort.'),
]

records=[]
start=date(2025,1,6)

def add(kind,i,suffix, title, content, context, decision, reasoning, trade, related, tags):
    rec={'id': f'{suffix}-{i+1:03d}', 'senior_id':'senior_001','type':kind,'title':title,
         'date':(start+timedelta(days=i*23+{'DOC':0,'ADR':2,'INC':4,'PR':6,'COM':7,'MENTOR':10}[suffix])).isoformat(),
         'project':'Orion Orders API','content':content,'context':context,'decision':decision,
         'reasoning':reasoning,'trade_offs':[trade], 'related_ids':related,'tags':[s['slug'],s['principle'],kind]}
    records.append(rec)

for i,s in enumerate(cases):
    uid=i+1
    doc=f'DOC-{uid:03d}'; adr=f'ADR-{uid:03d}'; pr=f'PR-{uid:03d}'
    inc=f'INC-{uid:03d}' if i<10 else None
    commit=f'COM-{uid:03d}' if i<10 else None
    add('technical_document',i,'DOC',f'{s["name"]}: system notes',
        f'The {s["component"]} is part of the fictional Orion Orders API. Observed failure mode: {s["symptom"]} Engineering evidence: {s["evidence"]} The runbook describes where to inspect logs, which measurement to collect, how to reproduce the scenario in a seeded staging environment, and how to verify the fix. Acceptance criterion: {s["measure"]} Operational recovery: {s["rollback"]}',
        f'Internal service documentation for the {s["component"]}, maintained as part of a reproducible training corpus.',
        f'Document diagnosis and validation steps for {s["name"].lower()}.',
        f'This document separates observations from opinions so future engineers can verify an earlier diagnosis. {s["gotcha"]}',
        s['downside'], [adr]+([inc] if inc else []), ['runbook']),
    add('architecture_decision',i,'ADR',f'ADR: {s["name"]}',
        f'Status: Accepted in the synthetic engineering history. Context: {s["symptom"]} Evidence considered: {s["evidence"]} Alex Morgan recommended: {s["action"]} Alternative considered and rejected for now: {s["alternative"]}. The decision is deliberately conditional: if measurements change, the team should revisit it. Validation: {s["measure"]} Rollback: {s["rollback"]}',
        f'The team must make an explicit architectural choice affecting the {s["component"]} and record its constraints.',
        s['action'],
        f'The recommendation follows evidence and stated production constraints rather than a universal rule. {s["gotcha"]}',
        s['downside'],[doc]+([inc] if inc else []),['decision']),
    add('pull_request',i,'PR',f'PR review: {s["name"]}',
        f'Proposed change: implement the mitigation for {s["name"].lower()}. Alex reviewed the change and asked for concrete evidence: {s["evidence"]} Review feedback: add a failing regression test, explain the chosen alternative, cover failure and retry paths, and make operational recovery explicit. Requested implementation: {s["action"]} The review remains conditional on this check: {s["measure"]} Alex explicitly noted: {s["gotcha"]}',
        f'Code review conversation about a production-facing change to the {s["component"]}.',
        f'Approve only after tests and measurement support this change: {s["action"]}',
        f'The review prioritizes maintainability and safe failure behavior. {s["gotcha"]}',
        s['downside'],[adr]+([commit] if commit else []), ['code_review']),
    if inc:
        add('incident',i,'INC',f'Incident: {s["name"]}',
            f'Synthetic incident timeline: support flagged an anomaly in the {s["component"]}. Symptom: {s["symptom"]} The on-call team checked correlated request logs and dependency metrics, then verified: {s["evidence"]} Alex separated immediate containment from the durable fix. Chosen fix: {s["action"]} Prevention: encode the regression in an automated test and update the runbook. Recovery procedure: {s["rollback"]}',
            f'A fictional production-like incident was escalated for the {s["component"]}; customer impact and recovery mattered.',
            s['action'],f'Alex required observable evidence before selecting the least risky remedy. {s["gotcha"]}',
            s['downside'],[doc,adr,pr]+([commit] if commit else []),['postmortem']),
        add('commit',i,'COM',f'Commit series: {s["name"]}',
            f'Commit summary: implement the agreed correction for {s["name"].lower()} with an isolated code path and regression coverage. Files in the fictitious service would include the component module, its tests, and the relevant runbook. The change follows ADR-{uid:03d}: {s["action"]} The commit notes explain why {s["alternative"].lower()} was not chosen. Verification required: {s["measure"]} Production safety note: {s["rollback"]}',
            f'A synthetic commit linked to incident remediation and review for the {s["component"]}.',
            f'Land the smallest tested implementation of the decision for {s["name"].lower()}.',
            f'A narrowly scoped change is easier to review and reverse; it must be backed by validation. {s["gotcha"]}',
            s['downside'],[adr,pr,inc],['implementation']),
    for variant in (1,2) if i<4 else (1,):
        # first four topics receive two mentoring conversations; all others one = 16
        j= len([r for r in records if r['type']=='mentoring'])+1
        if variant==1:
            junior=f'Junior: "I think we should use the fastest-looking option for {s["component"]}. Should we just {s["alternative"].lower()}?"'
            answer=f'Alex: "Before making that change, {s["coaching"]} Let us state the observation clearly: {s["evidence"]} What lower-risk option could address it? I would test this: {s["action"]} We will know if we were right by checking: {s["measure"]}"'
        else:
            junior=f'Junior: "A production alert just fired for {s["component"]}. Should I push my patch immediately?"'
            answer=f'Alex: "First tell me what users are experiencing and whether containment is needed. Our evidence is: {s["evidence"]} If this is security-sensitive, stop exposure immediately; otherwise check the rollback path. {s["rollback"]} Then propose a minimal tested change: {s["action"]} What regression test would catch this in the future?"'
        add('mentoring',i,'MENTOR',f'Mentoring {j:02d}: {s["name"]} ({"diagnosis" if variant==1 else "incident response"})',
            f'{junior} {answer} Follow-up note: Alex expects the junior to summarize the trade-off before merging. Known caveat: {s["downside"]} The junior should be able to explain why the selected solution fits the observed constraints instead of memorizing a technology preference.',
            f'A fictional one-to-one mentoring discussion about the {s["component"]}, with the junior asking for guidance.',
            f'Coach the junior to justify: {s["action"]}',
            f'The coaching uses a leading question and then gives evidence-based guidance. {s["gotcha"]}',
            s['downside'],[adr,doc]+([inc] if inc else []),['mentor_style','socratic']),

# Assign mentoring IDs consistently per topic: since add() currently uses i+1, fix duplicates and ensure references as needed.
mentor_num=0
for r in records:
    if r['type']=='mentoring':
        mentor_num+=1
        r['id']=f'MENTOR-{mentor_num:03d}'
# Ensure no IDs duplicated and all links internal.
ids=[r['id'] for r in records]
assert len(ids)==len(set(ids)), [k for k in set(ids) if ids.count(k)>1]
assert all(ref in ids for r in records for ref in r['related_ids'])
assert len(records)==72, len(records)
for r in records:
    assert len(r['content'])>=100 and len(r['context'])>=30 and len(r['decision'])>=20 and len(r['reasoning'])>=30
OUT.write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in records),encoding='utf-8')
from collections import Counter
print('Produced',len(records), Counter(r['type'] for r in records))
print('Bytes', OUT.stat().st_size)
